    @Test
    void testCreateRecommendation_WithVetRole_Success() throws Exception {
        RecommendationCreateRequest req = RecommendationCreateRequest.builder()
                .type("Ilac")
                .description("Gunde 2 kez antibiyotik")
                .build();

        mockMvc.perform(post("/visits/{visitId}/recommendations", testVisit.getId())
                .with(jwt().authorities(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_VET_STAFF")).jwt(j -> j.subject(vetStaffId.toString())))
                .contentType(MediaType.APPLICATION_JSON)
                .content(objectMapper.writeValueAsString(req)))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.type").value("Ilac"))
                .andExpect(jsonPath("$.description").value("Gunde 2 kez antibiyotik"));
    }

    @Test
    void testCreateRecommendation_WithNoVetRole_Forbidden() throws Exception {
        RecommendationCreateRequest req = RecommendationCreateRequest.builder()
                .type("Ilac")
                .description("Gunde 2 kez antibiyotik")
                .build();

        mockMvc.perform(post("/visits/{visitId}/recommendations", testVisit.getId())
                .with(jwt().authorities(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_OWNER")).jwt(j -> j.subject(ownerId.toString())))
                .contentType(MediaType.APPLICATION_JSON)
                .content(objectMapper.writeValueAsString(req)))
                .andExpect(status().isForbidden());
    }

    @Test
    void testGetRecommendationsByPetId_WithOwnerRole_Success() throws Exception {
        Recommendation rec = Recommendation.builder()
                .visitId(testVisit.getId())
                .type("Egzersiz")
                .description("Gunde 1 saat yuruyus")
                .createdBy(vetStaffId)
                .build();
        recommendationRepository.save(rec);

        mockMvc.perform(get("/pets/{id}/recommendations", testPet.getId())
                .with(jwt().authorities(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_OWNER")).jwt(j -> j.subject(ownerId.toString()))))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].type").value("Egzersiz"));
    }
